-- 007a_prod_roles_reconcile.sql
-- The production database was built from the older seed, where the owner role is called "Admin" and
-- there is no "Site Admin". The application code and migrations 023/025/037 address roles by name
-- ("Business Head", "Site Admin"), so on prod they would silently match nothing and the owner would
-- be locked out of newer screens (e.g. the Notifications API).
--
-- Run this BEFORE 008. It is a no-op on a database that already has "Business Head".
--   Admin (id 1)  -> renamed "Business Head", permissions reset to the current seed (migrations
--                    023/025/037 then extend them as usual)
--   Site Admin    -> created (nobody is assigned to it)
-- Sales Staff, Store Head -> permissions reset to the current seed, but only on such a legacy database
--                    (prod's older ones let Store Head manage users/roles/settings and see payroll, and lacked
--                    purchase-order approval; the app now reserves user management for Business Head).

do $$
declare
  bh_perms json := '[{"resource":"site","path":["/secure/settings/users","/secure/settings/store","/secure/dashboard","/secure/profile"]},{"resource":"roles","path":"/secure/settings/roles","policies":[{"action":"read","path":"","properties":["name","permissions"]},{"action":"add","path":"/new","properties":["name","permissions"]},{"action":"edit","path":"/edit","properties":["name","permissions"]},{"action":"delete"}]},{"resource":"users","path":"/secure/settings/users","policies":[{"action":"read","path":"","properties":["fullname","email","phone","location"]},{"action":"add","path":"/new","properties":["fullname","email","phone","location","role","password","storeids"]},{"action":"edit","path":"/edit","properties":["fullname","email","phone","location","role","storeids"]},{"action":"delete"}]},{"resource":"storesettings","path":"/secure/settings/store","policies":[{"action":"read"},{"action":"add"},{"action":"edit"},{"action":"delete"}]},{"resource":"products","path":"/secure/products","policies":[{"action":"price","path":"/price","properties":["title","description"]},{"action":"add","path":"/new","properties":["title","description"]},{"action":"edit","path":"/edit","properties":["title"]},{"action":"delete"}]},{"resource":"purchases","path":["/secure/purchases","/secure/purchases/vendors","/secure/settings/delivery-partners"],"policies":[{"action":"read","path":"/list","properties":["name"]},{"action":"add","path":"/new","properties":["name"]},{"action":"edit","path":"/edit","properties":["name"]},{"action":"vendors.edit","path":"vendors/edit","properties":["name"]},{"action":"delete"}]},{"resource":"purchaseorders","path":["/secure/purchases/orders"],"policies":[{"action":"approve"},{"action":"reject"}]},{"resource":"store","path":["/secure/store/stock","/secure/store/cash","/secure/store/shifts"],"policies":[{"action":"read","properties":["ptrcost"]},{"action":"adjust"},{"action":"shift.open"},{"action":"shift.close"}]},{"resource":"customers","path":"/secure/customers","policies":[{"action":"read","properties":[]}]},{"resource":"sales","path":["/secure/sales/pos","/secure/sales/pos/new","/secure/sales/list","/secure/sales/view","/secure/sales/new","/secure/sales/edit","/secure/sales/returns","/secure/sales/reminders","/secure/sales/deliveries"],"data":"all","policies":[{"action":"read","properties":[]},{"action":"view","properties":[]},{"action":"add","path":"/new","properties":[]},{"action":"bill","path":"/bill/print"}]},{"resource":"settings","path":["/secure/settings/users","/secure/settings/roles","/secure/settings/store"],"data":"all","policies":[{"action":"read","properties":[]},{"action":"view","properties":[]},{"action":"add","path":"/new","properties":[]}]},{"resource":"reports","path":["/secure/reports"]}]'::json;
  sh_perms json := '[{"resource":"site","path":["/secure/dashboard","/secure/profile"]},{"resource":"products","path":"/secure/products","policies":[{"action":"price","path":"/price","properties":["title","description"]},{"action":"add","path":"/new","properties":["title","description"]},{"action":"edit","path":"/edit","properties":["title"]},{"action":"delete"}]},{"resource":"purchases","path":["/secure/purchases","/secure/purchases/vendors","/secure/settings/delivery-partners"],"policies":[{"action":"read","path":"/list","properties":["name"]},{"action":"add","path":"/new","properties":["name"]},{"action":"edit","path":"/edit","properties":["name"]},{"action":"vendors.edit","path":"vendors/edit","properties":["name"]},{"action":"delete"}]},{"resource":"purchaseorders","path":"/secure/purchases/orders","policies":[{"action":"approve"},{"action":"reject"}]},{"resource":"store","path":["/secure/store/stock","/secure/store/cash","/secure/store/shifts"],"policies":[{"action":"read","properties":["ptrcost"]},{"action":"adjust"},{"action":"shift.open"},{"action":"shift.close"}]},{"resource":"customers","path":"/secure/customers","policies":[{"action":"read","properties":[]}]},{"resource":"sales","path":["/secure/sales/pos","/secure/sales/pos/new","/secure/sales/list","/secure/sales/view","/secure/sales/new","/secure/sales/edit","/secure/sales/returns","/secure/sales/reminders"],"data":"all","policies":[{"action":"read","properties":[]},{"action":"view","properties":[]},{"action":"add","path":"/new","properties":[]},{"action":"bill","path":"/bill/print"}]},{"resource":"reports","path":["/secure/reports"]}]'::json;
  ss_perms json := '[{"resource":"site","path":["/secure/sales","/secure/profile"]},{"resource":"stock","path":"/secure/stock","policies":[{"action":"read","properties":[]}]},{"resource":"customers","path":"/secure/customers","policies":[{"action":"read","properties":[]}]},{"resource":"sales","path":"/secure/sales","policies":[{"action":"read","properties":[]},{"action":"add","path":"/new","properties":[]}]},{"resource":"purchases","path":"/secure/purchases","policies":[{"action":"read","path":"/list","properties":[]}]},{"resource":"store","path":[],"policies":[{"action":"shift.open"},{"action":"shift.close"}]}]'::json;
  sa_perms json := '[{"resource":"site","path":["/secure/dashboard","/secure/profile","/secure/settings/businesses","/secure/settings/users"]},{"resource":"businesses","path":"/secure/settings/businesses","policies":[{"action":"manage"},{"action":"read"},{"action":"add"},{"action":"edit"},{"action":"delete"}]},{"resource":"roles","path":"/secure/settings/roles","policies":[{"action":"read","path":"","properties":["name","permissions"]},{"action":"add","path":"/new","properties":["name","permissions"]},{"action":"edit","path":"/edit","properties":["name","permissions"]},{"action":"delete"}]},{"resource":"users","path":"/secure/settings/users","policies":[{"action":"read","path":"","properties":["fullname","email","phone","location"]},{"action":"add","path":"/new","properties":["fullname","email","phone","location","password","businessid"]},{"action":"edit","path":"/edit","properties":["fullname","email","phone","location","businessid"]},{"action":"delete"}]},{"resource":"settings","path":["/secure/settings/businesses","/secure/settings/users","/secure/settings/roles"],"data":"all","policies":[{"action":"read","properties":[]},{"action":"view","properties":[]},{"action":"add","path":"/new","properties":[]}]}]'::json;
begin
  if not exists (select 1 from public.app_role where name = 'Business Head')
     and exists (select 1 from public.app_role where name = 'Admin') then
    update public.app_role
       set name = 'Business Head', permissions = bh_perms, updated_on = now()
     where name = 'Admin';
    update public.app_role set permissions = sh_perms, updated_on = now() where name = 'Store Head';
    update public.app_role set permissions = ss_perms, updated_on = now() where name = 'Sales Staff';
    raise notice 'Renamed role Admin to Business Head; reset Store Head and Sales Staff permissions';
  end if;

  if not exists (select 1 from public.app_role where name = 'Site Admin') then
    insert into public.app_role (name, permissions, locked, active, archive)
    values ('Site Admin', sa_perms, true, true, false);
    raise notice 'Created role Site Admin';
  end if;
end $$;
